/// `autonomous` — model acted without instruction; always upgrades to Signal.
pub fn derive_significance(
    schema: &PluginSchema,
    field: Option<&str>,
    is_write: bool,
    constraint_failed: bool,
    autonomous: bool,
) -> Significance { … }

